class QuestionRepository {
  constructor() {
    this.customQuestions = this.loadCustomQuestions();
    this.questions = [...INITIAL_YDS_QUESTIONS, ...this.customQuestions];
    this.customExams = typeof CUSTOM_EXAM_QUESTIONS !== 'undefined' ? CUSTOM_EXAM_QUESTIONS : [];
  }

  loadCustomQuestions() {
    try {
      const stored = typeof localStorage !== 'undefined' ? localStorage.getItem(STORAGE_KEYS.CUSTOM_QUESTIONS) : null;
      return stored ? JSON.parse(stored) : [];
    } catch (e) {
      console.error("Özel sorular yüklenemedi:", e);
      return [];
    }
  }

  saveCustomQuestions(questions) {
    try {
      localStorage.setItem(STORAGE_KEYS.CUSTOM_QUESTIONS, JSON.stringify(questions));
      this.customQuestions = questions;
      this.questions = [...INITIAL_YDS_QUESTIONS, ...this.customQuestions];
    } catch (e) {
      console.error("Özel sorular kaydedilemedi:", e);
    }
  }

  addCustomQuestions(newQuestions) {
    const toAdd = Array.isArray(newQuestions) ? newQuestions : [newQuestions];
    const updatedCustom = [...this.customQuestions, ...toAdd];
    this.saveCustomQuestions(updatedCustom);
    return toAdd.length;
  }

  // --- 1. GÜNÜN SORUSU HAVUZU (Sadece Çıkmış Sorular) ---
  getAll() {
    return this.questions;
  }

  // --- 2. ALIŞTIRMA SORULARI HAVUZU (Sadece Özgün Sorular) ---
  getPracticeQuestions() {
    if (typeof window !== 'undefined' && window.PRACTICE_YDS_QUESTIONS && window.PRACTICE_YDS_QUESTIONS.length > 0) {
      return window.PRACTICE_YDS_QUESTIONS;
    }
    if (typeof PRACTICE_YDS_QUESTIONS !== 'undefined' && PRACTICE_YDS_QUESTIONS.length > 0) {
      return PRACTICE_YDS_QUESTIONS;
    }
    return [];
  }

  getAlistirmaQuestions() {
    return this.getPracticeQuestions();
  }

  getAllExamQuestions() {
    return this.customExams;
  }

  getAllUserFacingQuestions() {
    return [...this.getPracticeQuestions(), ...this.customExams];
  }

  // --- 3. DENEMELER HAVUZU (Sadece Yeni Eklenen Denemeler) ---
  getAvailableExams() {
    const exams = [];
    const examMap = new Map();
    
    this.customExams.forEach(q => {
      if (!examMap.has(q.exam)) {
        examMap.set(q.exam, {
          id: q.exam,
          name: q.exam,
          year: q.year || "2025",
          term: q.term || "Özgün Deneme",
          count: 0
        });
      }
      examMap.get(q.exam).count++;
    });
    
    return Array.from(examMap.values());
  }

  getByExam(examName) {
    // app.js'teki eski uyumluluk için eğer examName sayı gelirse array index gibi davran
    if (typeof examName === 'number') {
      const examsList = this.getAvailableExams();
      if (examName > 0 && examName <= examsList.length) {
        examName = examsList[examName - 1].name;
      }
    }
    return this.customExams.filter(q => q.exam === examName).sort((a, b) => a.questionNumber - b.questionNumber);
  }

  getQuestionById(id) {
    if (id === null || id === undefined) return null;
    const strId = String(id);
    let found = this.customExams.find(q => String(q.id) === strId);
    if (found) return found;
    const practice = this.getPracticeQuestions();
    found = practice.find(q => String(q.id) === strId);
    if (found) return found;
    return this.questions.find(q => String(q.id) === strId) || null;
  }

  getByYear(year) {
    return [];
  }

  getAvailableYears() {
    return [];
  }

  resetToDefault() {
    localStorage.removeItem(STORAGE_KEYS.CUSTOM_QUESTIONS);
    this.customQuestions = [];
    this.questions = [...INITIAL_YDS_QUESTIONS];
    return this.questions;
  }
}


if (typeof window !== 'undefined') {
  window.questionRepo = new QuestionRepository();
  window.STORAGE_KEYS = STORAGE_KEYS;
  window.INITIAL_YDS_QUESTIONS = INITIAL_YDS_QUESTIONS;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { INITIAL_YDS_QUESTIONS, QuestionRepository, STORAGE_KEYS, getExamChronologicalScore };
}
